import re, datetime as dt

def trasforma(campi):
    m = re.search(r'(\d+)', str(campi['CondizioniPagamento']))
    gg = int(m.group(1)) if m else 0
    d = dt.date.fromisoformat(campi['DataFattura']) + dt.timedelta(days=gg)
    return {'scadenza': d.isoformat()}
